<?php require_once __DIR__.'/../../includes/auth.php';requireSuperAdmin();require_once __DIR__.'/../../includes/functions.php';$logs=$pdo->query("SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 300")->fetchAll();$pageTitle='Audit Logs';require __DIR__.'/../../includes/header.php';require __DIR__.'/../../includes/sidebar.php';?><main class="main"><?php require __DIR__.'/../../includes/topbar.php';?><section class="content"><div class="mb-4"><span class="section-kicker">SECURITY</span><h1 class="page-title">Audit Logs</h1><p class="page-subtitle">Administrative actions and security events.</p></div><div class="panel"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Entity</th><th>Description</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['full_name']??'System')?></td><td><span class="badge bg-light text-dark"><?=e($l['action'])?></span></td><td><?=e($l['entity_type']??'')?> <?=e($l['entity_id']??'')?></td><td><?=e($l['description']??'')?></td><td><?=e($l['ip_address']??'')?></td></tr><?php endforeach;if(!$logs):?><tr><td colspan="6" class="text-center py-5 text-muted">No audit events yet.</td></tr><?php endif;?></tbody></table></div></div></section></main><?php require __DIR__.'/../../includes/footer.php';?>
